RSpec.describe Timekeeping::Gateway, "forwarded detach credentials" do
  let(:detach_credentials_base_url) { "http://timekeeping.test" }

  def detach_credentials_authorization(request)
    request[:headers].find { |name, _value| name.to_s.casecmp?("authorization") }&.last.to_s
  end

  # "The forwarded call uses a token bound to the agent's company that grants only agents.detach_entries, never TIMEKEEPING_SERVICE_TOKEN"
  # "Never send `TIMEKEEPING_SERVICE_TOKEN` outbound, and never use a user token here."
  it "forwards a detach with a service token bound to the agent's company and never the shared service token" do
    agent = create(:agent)
    other_company = create(:company)
    create(:employment, company: other_company, user: agent.user)
    fake = TimekeepingContract::FakeTimekeeping.new(token_public_key: timekeeping_key_pair.public_key)
    route_timekeeping_to_fake(fake, base_url: detach_credentials_base_url)
    TimekeepingOwnership.find(TimekeepingOwnership::SINGLETON_ID)
      .update_columns(owner: "timekeeping", generation: fake.generation)
    context = Timekeeping::WriteContext.new(company: agent.company, actor: agent.user, actor_kind: "agent_destroy",
                                            request_id: SecureRandom.uuid)

    shared_token = nil
    with_timekeeping_service_token do |token|
      shared_token = token
      with_timekeeping_env(
        Timekeeping::EntryApiClient::BASE_URL_ENV => detach_credentials_base_url,
        Timekeeping::UserToken::PRIVATE_KEY_ENV => timekeeping_key_pair.to_pem
      ) do
        described_class.new(context:).detach_agent_entries(agent:)
      end
    end

    expect(fake.requests.size).to eq(1)
    request = fake.requests.first
    expect(request[:method]).to eq("POST")
    expect(request[:path]).to eq("/v1/companies/#{agent.company_id}/agents/#{agent.id}/detach-entries")
    expect(request.to_s).not_to include(shared_token)

    authorization = detach_credentials_authorization(request)
    expect(authorization).to start_with("Bearer ")
    claims, = JWT.decode(authorization.delete_prefix("Bearer "), timekeeping_key_pair.public_key, true,
                         algorithm: "RS256")
    expect(claims["typ"]).to eq("timekeeping_service")
    expect(claims["company_id"]).to eq(agent.company_id)
    expect(claims["company_id"]).not_to eq(other_company.id)
    expect(claims["operations"]).to eq(["agents.detach_entries"])
    expect(claims["sub"]).to be_a(String)
    expect(claims).not_to have_key("role")
    expect(claims).not_to have_key("purpose")
  end
end

